<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import PdfEvidenceViewer from './PdfEvidenceViewer.vue';
import PdfPageLabelEditor from './PdfPageLabelEditor.vue';
import { useI18nStore } from '../stores/i18n';
import type { DocumentLayoutPlan, PdfAsset, SourceBlock } from '../api/pdfCorpus';
const props=withDefaults(defineProps<{asset:PdfAsset;pdfUrl:string;blocks?:SourceBlock[];disabled?:boolean;saving?:boolean}>(),{blocks:()=>[],disabled:false,saving:false});
const emit=defineEmits<{save:[plan:DocumentLayoutPlan];savePageLabels:[labels:Record<number,string|null>];pageChange:[page:number]}>();
const i18n=useI18nStore(); const current=ref(1); const draft=ref<DocumentLayoutPlan>({page_layout:'single',reading_order:'left_to_right',thread_mode:'continuous'});
function normalized(plan?:DocumentLayoutPlan|null){return {page_layout:plan?.page_layout??'single',reading_order:plan?.reading_order??'left_to_right',thread_mode:plan?.thread_mode??'continuous',main_text_pdf_start:plan?.main_text_pdf_start??null,main_text_printed_start:plan?.main_text_printed_start??null,main_text_slot:plan?.main_text_slot??null,bibliography_pdf_start:plan?.bibliography_pdf_start??null,thread_a_language:plan?.thread_a_language??'',thread_b_language:plan?.thread_b_language??''}}
watch(()=>props.asset.document_layout,plan=>{draft.value={...normalized(plan)} as DocumentLayoutPlan},{immediate:true,deep:true});
const dirty=computed(()=>JSON.stringify(normalized(draft.value))!==JSON.stringify(normalized(props.asset.document_layout)));
const pageInfo=computed(()=>props.asset.pages?.find(p=>p.pdf_page===current.value));
type LogicalPagePreview={slot:string;printed_page_label?:string|null};
const logicalPreview=computed<LogicalPagePreview[]>(()=>pageInfo.value?.logical_pages||[]);
const mappedCount=computed(()=>props.asset.pages?.filter(page=>Boolean(String(page.printed_page_label??'').trim())||(page.logical_pages||[]).some(item=>Boolean(String(item.printed_page_label??'').trim()))).length||0);
const exceptionCount=computed(()=>props.asset.pages?.filter(page=>String(page.printed_page_label_source||'').includes('override')).length||0);
function setPage(value:number){current.value=Math.max(1,Math.min(props.asset.page_count||1,value));emit('pageChange',current.value)}
function save(){if(!dirty.value||props.saving)return;emit('save',{...draft.value})}
</script>
<template><section class="structure-config" aria-labelledby="document-structure-title">
<header><div><span class="eyebrow">{{i18n.t('pdf_corpus.document_structure','Document structure & pagination')}}</span><h3 id="document-structure-title">{{asset.filename}}</h3><p>{{i18n.t('pdf_corpus.document_structure_help','Describe physical page layout and a few reliable anchors. DerridAI derives printed-page labels, structural regions, and thread hints deterministically before asking an LLM to interpret records.')}}</p></div><div class="save-state"><span :data-state="saving?'saving':dirty?'dirty':'saved'" role="status" aria-live="polite">{{saving?i18n.t('ui.saving','Saving…'):dirty?i18n.t('pdf_corpus.unsaved_structure','Unsaved changes'):i18n.t('pdf_corpus.structure_saved_state','Saved')}}</span><button class="btn primary" type="button" :disabled="disabled||saving||!dirty" @click="save">{{saving?i18n.t('ui.saving','Saving…'):i18n.t('pdf_corpus.save_document_structure','Save document structure')}}</button></div></header>
<div class="structure-grid"><section class="browser"><div class="page-nav"><button class="btn small" type="button" :disabled="current<=1" @click="setPage(current-1)">← {{i18n.t('ui.previous','Previous')}}</button><label><span class="sr-only">{{i18n.t('pdf_corpus.physical_pdf_page','Physical PDF page')}}</span><input class="control compact" type="number" min="1" :max="asset.page_count" :value="current" @change="setPage(Number(($event.target as HTMLInputElement).value))"></label><span>/ {{asset.page_count}}</span><button class="btn small" type="button" :disabled="current>=asset.page_count" @click="setPage(current+1)">{{i18n.t('ui.next','Next')}} →</button></div><PdfEvidenceViewer :pdf-url="pdfUrl" :page="current" :page-width="pageInfo?.width||0" :page-height="pageInfo?.height||0" :blocks="blocks||[]"/><div v-if="draft.page_layout==='two_up'" class="two-up-preview" :aria-label="i18n.t('pdf_corpus.two_up_logical_preview','Two-up logical page preview')"><span v-for="item in logicalPreview.length?logicalPreview:[{slot:'left',printed_page_label:null},{slot:'right',printed_page_label:null}]" :key="item.slot"><b>{{i18n.t(`pdf_corpus.${item.slot}_page`,item.slot)}}</b><small>{{item.printed_page_label?i18n.tf('pdf_corpus.printed_page_value','printed p. {page}',{page:item.printed_page_label}):i18n.t('pdf_corpus.not_mapped_yet','not mapped yet')}}</small></span></div><div class="current-page-actions"><button class="btn" type="button" @click="draft.main_text_pdf_start=current">{{i18n.t('pdf_corpus.set_current_main_start','Set current as main-text start')}}</button><button class="btn" type="button" @click="draft.bibliography_pdf_start=current">{{i18n.t('pdf_corpus.set_current_bibliography','Set current as bibliography start')}}</button></div></section>
<section class="rules"><fieldset><legend>{{i18n.t('pdf_corpus.page_layout','Page layout')}}</legend><label class="radio-row"><input v-model="draft.page_layout" type="radio" value="single"> <span>{{i18n.t('pdf_corpus.single_page_layout','1 printed page per PDF page')}}</span></label><label class="radio-row"><input v-model="draft.page_layout" type="radio" value="two_up"> <span>{{i18n.t('pdf_corpus.two_up_layout','2 printed pages per PDF page')}}</span></label><label v-if="draft.page_layout==='two_up'"><span>{{i18n.t('pdf_corpus.reading_order','Reading order')}}</span><select v-model="draft.reading_order" class="control"><option value="left_to_right">{{i18n.t('pdf_corpus.left_to_right','Left → right')}}</option><option value="right_to_left">{{i18n.t('pdf_corpus.right_to_left','Right → left')}}</option></select></label></fieldset>
<fieldset><legend>{{i18n.t('pdf_corpus.structural_anchors','Structural anchors')}}</legend><label><span>{{i18n.t('pdf_corpus.main_text_starts_pdf','First main-text page appears on PDF page')}}</span><div class="anchor"><input v-model.number="draft.main_text_pdf_start" class="control" type="number" min="1" :max="asset.page_count"><button class="btn small" type="button" @click="draft.main_text_pdf_start=current">{{i18n.t('pdf_corpus.use_current_page','Use current')}}</button></div></label><label><span>{{i18n.t('pdf_corpus.first_printed_page_number','Printed page number at main-text start')}}</span><input v-model.number="draft.main_text_printed_start" class="control" type="number" min="1"></label><label v-if="draft.page_layout==='two_up'"><span>{{i18n.t('pdf_corpus.main_text_slot','Main text begins on')}}</span><select v-model="draft.main_text_slot" class="control"><option value="left">{{i18n.t('pdf_corpus.left_page','Left page')}}</option><option value="right">{{i18n.t('pdf_corpus.right_page','Right page')}}</option></select></label><label><span>{{i18n.t('pdf_corpus.bibliography_starts_pdf','Bibliography begins on PDF page')}}</span><div class="anchor"><input v-model.number="draft.bibliography_pdf_start" class="control" type="number" min="1" :max="asset.page_count"><button class="btn small" type="button" @click="draft.bibliography_pdf_start=current">{{i18n.t('pdf_corpus.use_current_page','Use current')}}</button></div></label></fieldset>
<fieldset><legend>{{i18n.t('pdf_corpus.page_threads','Page threads')}}</legend><label><span>{{i18n.t('pdf_corpus.thread_pattern','Thread pattern')}}</span><select v-model="draft.thread_mode" class="control"><option value="continuous">{{i18n.t('pdf_corpus.thread_continuous','Single continuous sequence')}}</option><option value="odd_even">{{i18n.t('pdf_corpus.thread_odd_even','Odd PDF pages = A; even = B')}}</option><option value="even_odd">{{i18n.t('pdf_corpus.thread_even_odd','Even PDF pages = A; odd = B')}}</option><option value="left_right" :disabled="draft.page_layout!=='two_up'">{{i18n.t('pdf_corpus.thread_left_right','Left logical pages = A; right = B')}}</option><option value="right_left" :disabled="draft.page_layout!=='two_up'">{{i18n.t('pdf_corpus.thread_right_left','Right logical pages = A; left = B')}}</option></select></label><div v-if="draft.thread_mode!=='continuous'" class="thread-languages"><label><span>{{i18n.t('pdf_corpus.thread_a_language','Thread A language (optional)')}}</span><input v-model="draft.thread_a_language" class="control" placeholder="en_us"></label><label><span>{{i18n.t('pdf_corpus.thread_b_language','Thread B language (optional)')}}</span><input v-model="draft.thread_b_language" class="control" placeholder="fr_fr"></label></div></fieldset></section></div>
<section class="mapping-summary"><div><b>{{i18n.t('pdf_corpus.generated_mapping','Generated page mapping')}}</b><span>{{i18n.tf('pdf_corpus.mapping_summary','{mapped} of {total} PDF pages mapped · {exceptions} exception(s)',{mapped:mappedCount,total:asset.page_count,exceptions:exceptionCount})}}</span></div><details class="exceptions"><summary class="btn">{{i18n.t('pdf_corpus.review_mapping','Review mapping')}}</summary><p>{{i18n.t('pdf_corpus.mapping_exceptions_help','Use per-page overrides only for exceptions. Deterministic rules remain the default mapping source.')}}</p><PdfPageLabelEditor :pages="asset.pages||[]" :disabled="disabled" @save="labels=>emit('savePageLabels',labels)"/></details></section>
</section></template>
<style scoped>.structure-config{container-type:inline-size;display:grid;gap:16px;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--card)}.structure-config>header{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.structure-config h3{margin:2px 0;font-size:1rem}.structure-config header p{margin:4px 0 0;max-width:78ch;color:var(--muted);font-size:.875rem;line-height:1.45}.eyebrow{font-size:.75rem;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);font-weight:800}.save-state{display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:flex-end}.save-state span{font-size:.8125rem;font-weight:750;color:var(--muted)}.save-state span[data-state="dirty"]{color:var(--warning,#8a6200)}.save-state span[data-state="saved"]{color:var(--success,#166534)}.structure-grid{display:grid;grid-template-columns:minmax(520px,1.2fr) minmax(360px,.8fr);gap:18px;align-items:start}.browser,.rules fieldset{min-width:0;border:1px solid var(--line);border-radius:10px;background:var(--soft)}.browser{overflow:hidden;position:sticky;top:78px;align-self:start}.page-nav{display:flex;gap:7px;align-items:center;padding:9px;border-bottom:1px solid var(--line);background:var(--card)}.page-nav input{width:76px}.rules{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;align-content:start}.rules fieldset{display:grid;gap:9px;margin:0;padding:12px}.rules fieldset:nth-child(2){grid-row:auto}.rules legend{padding:0 4px;font-size:.875rem;font-weight:800}.rules label{display:grid;gap:5px;font-size:.8125rem;line-height:1.4}.radio-row{display:flex!important;align-items:flex-start;gap:8px}.rules input[type=radio]{inline-size:18px;block-size:18px;flex:none}.anchor{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px}.thread-languages{display:grid;grid-template-columns:1fr;gap:8px}.two-up-preview{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--line);background:var(--card)}.two-up-preview span{display:grid;gap:2px;padding:8px 10px;border-inline-end:1px solid var(--line)}.two-up-preview small{color:var(--muted)}.current-page-actions{display:flex;gap:8px;flex-wrap:wrap;padding:10px;background:var(--card);border-top:1px solid var(--line)}.mapping-summary{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--soft)}.mapping-summary>div{display:grid;gap:3px}.mapping-summary span,.exceptions>p{color:var(--muted);font-size:.8125rem;line-height:1.45}.exceptions{min-width:min(460px,100%)}.exceptions summary{list-style:none;cursor:pointer;width:max-content}.exceptions summary::-webkit-details-marker{display:none}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.structure-config :is(input,select,button,summary):focus-visible{outline:3px solid var(--accent);outline-offset:2px}@container (max-width:900px){.structure-grid{grid-template-columns:1fr}.browser{position:static}.rules{grid-template-columns:1fr}.mapping-summary{flex-direction:column}.exceptions{min-width:0;width:100%}}@media(max-width:1120px){.structure-grid{grid-template-columns:1fr}.browser{position:static}.rules{grid-template-columns:1fr}.mapping-summary{flex-direction:column}.exceptions{min-width:0;width:100%}}@media(max-width:720px){.structure-config>header,.save-state{align-items:stretch;flex-direction:column}.rules{grid-template-columns:1fr}.rules fieldset:nth-child(2){grid-row:auto}.anchor{grid-template-columns:1fr}.current-page-actions .btn{flex:1 1 100%}}
</style>
